		appended = new IRI[COMMIT_BATCH];
		for (int i = 0; i < predicates.length; i++) {
			predicates[i] = values.createIRI("urn:adjacency-benchmark:predicate:" + i);
			expectedGroupChecksum += predicates[i].stringValue().hashCode() * (long) (statementCount / 8);
		}
		for (int i = 0; i < contexts.length; i++) {
			contexts[i] = values.createIRI("urn:adjacency-benchmark:context:" + i);
		}
